/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
zones=[('.', '10.14.1.11'),('com','10.14.1.12'),('net','10.14.1.13'),('example.com','10.14.1.14'),('service.com','10.14.2.11'),('lab.net','10.14.2.12'),('tools.net','10.14.2.13'),('shop.example.com','10.14.3.11'),('api.service.com','10.14.3.12'),('research.lab.net','10.14.3.13'),('ci.tools.net','10.14.4.11'),('ai.research.lab.net','10.14.4.12'),('data.research.lab.net','10.14.4.13')]
children={0:[1,2],1:[3,4],2:[5,6],3:[7],4:[8],5:[9],6:[10],9:[11,12]}
extras={3:['www IN A 10.14.5.11','mail IN A 10.14.1.14','@ IN MX 10 mail.example.com.'],4:['mail IN A 10.14.2.11','@ IN MX 10 mail.service.com.'],5:['mail IN A 10.14.2.12','@ IN MX 10 mail.lab.net.'],6:['mail IN A 10.14.2.13','@ IN MX 10 mail.tools.net.']}
def ns(zone): return 'ns.root.' if zone=='.' else 'ns.'+zone+'.'
for i,(zone,ip) in enumerate(zones):
 p=Path(f'pc{i+1}/etc/bind'); p.mkdir(parents=True,exist_ok=True)
 config='''options {
    directory \"/var/cache/bind\";
    pid-file \"/run/named/named.pid\";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
    dnssec-validation no;
    empty-zones-enable no;
};
zone \"%s\" { type master; file \"/etc/bind/db.lab\"; };
''' % zone
 (p/'named.conf').write_text(config)
 lines=['"'$TTL 300'"',f'@ IN SOA {ns(zone)} hostmaster.{\"root.\" if zone==\".\" else zone+\".\"} ( 1 3600 600 86400 300 )',f'@ IN NS {ns(zone)}',f'{ns(zone)} IN A {ip}']
 if i in [7,8,10,11,12]: lines.append(f'@ IN A {ip}')
 lines += extras.get(i,[])
 for j in children.get(i,[]):
  child,addr=zones[j]; lines.extend([f'{child}. IN NS {ns(child)}',f'{ns(child)} IN A {addr}'])
 (p/'db.lab').write_text('\\n'.join(lines)+'\\n')
 startup=Path(f'pc{i+1}.startup'); startup.write_text(startup.read_text()+'\\n# Start the authoritative DNS server.\\nmkdir -p /run/named /var/cache/bind\\nnamed -4 -c /etc/bind/named.conf\\n')
p=Path('pc14/etc/bind'); p.mkdir(parents=True,exist_ok=True)
(p/'named.conf').write_text('''options {
    directory \"/var/cache/bind\";
    pid-file \"/run/named/named.pid\";
    listen-on { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { 10.14.0.0/16; localhost; };
    dnssec-validation no;
    empty-zones-enable no;
};
zone \".\" { type hint; file \"/etc/bind/db.root.lab\"; };
''')
(p/'db.root.lab').write_text('. 300 IN NS ns.root.\\nns.root. 300 IN A 10.14.1.11\\n')
s=Path('pc14.startup'); s.write_text(s.read_text()+'\\n# Start the recursive resolver using the laboratory root.\\nmkdir -p /run/named /var/cache/bind\\nnamed -4 -c /etc/bind/named.conf\\n')
for i in range(16,21):
 s=Path(f'pc{i}.startup'); s.write_text(s.read_text()+\"\\n# Use the laboratory recursive resolver.\\nprintf 'nameserver 10.14.4.14\\\\n' > /etc/resolv.conf\\n\")
Path('DNS-README.md').write_text('''# Laboratory DNS\\n\\nThe authoritative servers run BIND on pc1–pc13; pc14 resolves recursively using pc1 (10.14.1.11) as its only root hint. Clients pc16–pc20 use pc14 (10.14.4.14). DNSSEC validation is disabled for this unsigned private hierarchy.\\n\\nNo web service was present in the original lab. The "'`www.example.com` record points to the existing pc15 address, 10.14.5.11; the DNS configuration does not install a web server.'"\\n\\nThe PC images must provide BIND 9 ("'`named`). After starting the lab, test e.g. `dig @10.14.4.14 ai.research.lab.net A` and `dig @10.14.4.14 example.com MX` from a client.'"\\n''')
PY
for f in pc{1..14}.startup pc{16..20}.startup; do sh -n \""'$f" || exit; done'

